-- Operations case and knowledge schema. Generated by go run ./cmd/ops-schema.
CREATE TABLE IF NOT EXISTS "ops_case" ("id" bigserial,"group_id" bigint NOT NULL,"severity" bigint,"title" varchar(255) NOT NULL,"state" varchar(24) NOT NULL,"wait_reason" varchar(64) NOT NULL DEFAULT '',"owner_id" bigint NOT NULL DEFAULT 0,"target_ident" varchar(255) NOT NULL DEFAULT '',"datasource_id" bigint NOT NULL DEFAULT 0,"rule_id" bigint NOT NULL DEFAULT 0,"context" TEXT,"knowledge_version_id" bigint NOT NULL DEFAULT 0,"plan_id" bigint NOT NULL DEFAULT 0,"revision" bigint NOT NULL DEFAULT 1,"generation" bigint NOT NULL DEFAULT 1,"close_type" varchar(40) NOT NULL DEFAULT '',"summary" text,"followup" text,"created_by" bigint,"created_at" bigint,"updated_at" bigint,"closed_at" bigint,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_ops_case_created_at" ON "ops_case" ("created_at");
CREATE INDEX IF NOT EXISTS "idx_ops_case_owner_id" ON "ops_case" ("owner_id");
CREATE INDEX IF NOT EXISTS "idx_ops_case_group_state" ON "ops_case" ("group_id","state");
CREATE TABLE IF NOT EXISTS "ops_episode" ("id" bigserial,"case_id" bigint NOT NULL,"group_id" bigint NOT NULL,"incident_id" varchar(64) NOT NULL,"sequence" bigint,"recovered" boolean,"snapshot" TEXT,"updated_at" bigint,PRIMARY KEY ("id"),CONSTRAINT "uni_ops_episode_incident_id" UNIQUE ("incident_id"));
CREATE INDEX IF NOT EXISTS "idx_ops_episode_group_id" ON "ops_episode" ("group_id");
CREATE INDEX IF NOT EXISTS "idx_ops_episode_case_id" ON "ops_episode" ("case_id");
CREATE TABLE IF NOT EXISTS "ops_inbox" ("id" bigserial,"dispatch_id" varchar(64) NOT NULL,"incident_id" varchar(64) NOT NULL,"case_id" bigint NOT NULL,"created_at" bigint,PRIMARY KEY ("id"),CONSTRAINT "uni_ops_inbox_dispatch_id" UNIQUE ("dispatch_id"));
CREATE INDEX IF NOT EXISTS "idx_ops_inbox_case_id" ON "ops_inbox" ("case_id");
CREATE INDEX IF NOT EXISTS "idx_ops_inbox_incident_id" ON "ops_inbox" ("incident_id");
CREATE TABLE IF NOT EXISTS "ops_evidence" ("id" bigserial,"case_id" bigint NOT NULL,"generation" bigint,"kind" varchar(40) NOT NULL,"source" varchar(255) NOT NULL,"status" varchar(24) NOT NULL,"observed_at" bigint,"window_start" bigint,"window_end" bigint,"collected_at" bigint,"payload" TEXT,"sha256" varchar(64) NOT NULL,"created_by" bigint,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_ops_evidence_case_id" ON "ops_evidence" ("case_id");
CREATE TABLE IF NOT EXISTS "ops_step" ("plan_id" bigint NOT NULL DEFAULT 0,"id" bigserial,"case_id" bigint NOT NULL,"generation" bigint,"version_id" bigint,"step_key" varchar(64) NOT NULL,"state" varchar(24) NOT NULL,"evidence_ids" TEXT,"note" text,"created_by" bigint,"created_at" bigint,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_ops_step_case_id" ON "ops_step" ("case_id");
CREATE TABLE IF NOT EXISTS "ops_audit" ("id" bigserial,"case_id" bigint NOT NULL,"actor_id" bigint,"action" varchar(64) NOT NULL,"detail" TEXT,"created_at" bigint,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_ops_audit_case_id" ON "ops_audit" ("case_id");
CREATE TABLE IF NOT EXISTS "ops_action" ("plan_id" bigint NOT NULL DEFAULT 0,"id" bigserial,"case_id" bigint NOT NULL,"generation" bigint,"version_id" bigint,"kind" varchar(32) NOT NULL,"state" varchar(24) NOT NULL,"operation_key" varchar(64) NOT NULL,"baseline" varchar(64) NOT NULL,"payload" TEXT,"result" TEXT,"proposed_by" bigint,"approved_by" bigint,"expires_at" bigint,"created_at" bigint,"updated_at" bigint,PRIMARY KEY ("id"),CONSTRAINT "uni_ops_action_operation_key" UNIQUE ("operation_key"));
CREATE INDEX IF NOT EXISTS "idx_ops_action_state" ON "ops_action" ("state");
CREATE INDEX IF NOT EXISTS "idx_ops_action_case_id" ON "ops_action" ("case_id");
CREATE TABLE IF NOT EXISTS "ops_verification" ("plan_id" bigint NOT NULL DEFAULT 0,"id" bigserial,"case_id" bigint NOT NULL,"generation" bigint,"version_id" bigint,"check_key" varchar(64) NOT NULL,"state" varchar(24) NOT NULL,"reason" text,"evidence_ids" TEXT,"confirmed_by" bigint,"created_at" bigint,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_ops_verification_case_id" ON "ops_verification" ("case_id");
CREATE TABLE IF NOT EXISTS "ops_run" ("id" bigserial,"case_id" bigint NOT NULL,"active_case_id" bigint,"user_id" bigint,"state" varchar(24) NOT NULL,"fence" bigint NOT NULL DEFAULT 0,"lease_until" bigint,"next_run_at" bigint,"attempts" bigint,"mode" varchar(24) NOT NULL,"result" text,"created_at" bigint,"updated_at" bigint,PRIMARY KEY ("id"),CONSTRAINT "uni_ops_run_active_case_id" UNIQUE ("active_case_id"));
CREATE INDEX IF NOT EXISTS "idx_ops_run_state" ON "ops_run" ("state");
CREATE INDEX IF NOT EXISTS "idx_ops_run_case_id" ON "ops_run" ("case_id");
CREATE TABLE IF NOT EXISTS "ops_policy" ("id" bigserial,"group_id" bigint NOT NULL,"enabled" boolean,"service_user_id" bigint,"auto_investigate" boolean,"rule_ids" TEXT,"revision" bigint NOT NULL DEFAULT 1,"scan_at" bigint,"scan_id" bigint,"reconcile_at" bigint,"health" varchar(255),"gap_since" bigint,PRIMARY KEY ("id"),CONSTRAINT "uni_ops_policy_group_id" UNIQUE ("group_id"));
CREATE TABLE IF NOT EXISTS "ops_plan" ("id" bigserial,"case_id" bigint NOT NULL,"sequence" bigint NOT NULL,"title" varchar(255) NOT NULL,"scope" text,"rationale" text,"payload" TEXT,"evidence_ids" TEXT,"sha256" varchar(64) NOT NULL,"generation" bigint,"evidence_anchor" bigint,"confirmed_generation" bigint,"state" varchar(24) NOT NULL,"created_by" bigint,"created_at" bigint,"confirmed_by" bigint,"confirmed_at" bigint,"decision_note" text,PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "idx_ops_plan_case_sequence" ON "ops_plan" ("case_id","sequence");
CREATE TABLE IF NOT EXISTS "ops_knowledge" ("id" bigserial,"group_id" bigint NOT NULL,"title" varchar(255) NOT NULL,"draft" TEXT,"revision" bigint NOT NULL DEFAULT 1,"current_version_id" bigint NOT NULL DEFAULT 0,"created_by" bigint,"updated_by" bigint,"updated_at" bigint,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_ops_knowledge_group_id" ON "ops_knowledge" ("group_id");
CREATE TABLE IF NOT EXISTS "ops_knowledge_version" ("id" bigserial,"item_id" bigint NOT NULL,"group_id" bigint NOT NULL,"sequence" bigint NOT NULL,"title" varchar(255) NOT NULL,"payload" TEXT,"sha256" varchar(64) NOT NULL,"published_by" bigint,"published_at" bigint,"withdrawn_at" bigint,"withdraw_reason" text,PRIMARY KEY ("id"));
CREATE INDEX IF NOT EXISTS "idx_ops_knowledge_version_group_id" ON "ops_knowledge_version" ("group_id");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_ops_knowledge_sequence" ON "ops_knowledge_version" ("item_id","sequence");
CREATE TABLE IF NOT EXISTS "ops_knowledge_source" ("id" bigserial,"group_id" bigint NOT NULL,"name" varchar(255) NOT NULL,"media_type" varchar(120) NOT NULL,"storage_key" varchar(64) NOT NULL,"sha256" varchar(64) NOT NULL,"size" bigint,"description" text,"created_by" bigint,"created_at" bigint,PRIMARY KEY ("id"),CONSTRAINT "uni_ops_knowledge_source_storage_key" UNIQUE ("storage_key"));
CREATE INDEX IF NOT EXISTS "idx_ops_knowledge_source_group_id" ON "ops_knowledge_source" ("group_id");
